insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_8_v1'
from (values
('127.51.d.1.A',2,'A student in veterinary science wants to map out a future job. Which choice lists real paths to explore?','["Veterinary technician, veterinarian, or clinic owner", "Animal clipper only", "Pet toy designer only", "Kennel painter only"]'::jsonb,0,'Vet science leads to many careers, including technician, veterinarian and practice owner. Learning the education needed for each helps with planning.','original'),
('127.51.d.1.A',3,'Which step best helps a vet science student compare career and education options?','["Picking whatever a friend picked", "Researching the schooling, licensing, and pay for each job", "Waiting until after graduation to look", "Choosing the job with the shortest name"]'::jsonb,1,'Comparing training, licensing and pay for several jobs gives facts for a good decision.','original'),
('127.51.d.1.B',2,'In a vet clinic, which habit shows professionalism?','["Skipping tasks nobody checks", "Texting during appointments", "Arriving on time and ready to work", "Leaving messes for the next shift"]'::jsonb,2,'Reliable attendance and focus are core work habits that build trust with clients and coworkers.','original'),
('127.51.d.1.B',3,'A clinic assistant is stuck on a scheduling conflict. What is the most professional response?','["Ignore the problem", "Quit the task without telling anyone", "Blame a coworker", "Think through options and ask a supervisor if needed"]'::jsonb,3,'Problem solving and asking for help when needed are signs of professionalism.','original'),
('127.51.d.1.C',2,'Why must a veterinary worker wear gloves when handling a sick animal?','["To protect against germs and infection", "To look more official", "To keep the animal warm", "To make the animal sit still"]'::jsonb,0,'Protective gear reduces the chance of spreading disease between animals and people.','original'),
('127.51.d.1.C',3,'Which is a safe practice in a veterinary workplace?','["Hiding minor bites", "Reporting injuries and hazards right away", "Skipping eye protection to save time", "Lifting heavy animals alone without help"]'::jsonb,1,'Prompt reporting lets the clinic treat injuries and fix hazards before others are hurt.','original'),
('127.51.d.1.D',3,'A veterinary employee reads about client privacy. This is an example of an employee:','["Right to share records online", "Option to gossip about owners", "Responsibility to keep client and patient records private", "Duty to post pet photos publicly"]'::jsonb,2,'Confidentiality is an ethical duty in veterinary work. Records are shared only with permission or as the law requires.','original'),
('127.51.d.1.D',4,'Which action shows ethical conduct for a vet assistant who makes a mistake with a medication label?','["Blaming the owner", "Hoping nobody notices", "Quietly relabeling and saying nothing", "Telling the supervisor right away so it can be corrected"]'::jsonb,3,'Honesty about errors protects the patient and keeps the clinic accountable.','original'),
('127.51.d.1.E',2,'Which action shows good citizenship in the animal health field?','["Volunteering at a local animal shelter vaccination day", "Avoiding all community events", "Ignoring community rules", "Dumping medical waste in trash cans"]'::jsonb,0,'Citizenship includes giving time to community animal care projects and following the rules that protect public health.','original'),
('127.51.d.1.E',3,'A good citizen who works with animals would:','["Skip pet licensing", "Follow local licensing and rabies laws", "Hide sick animals from officials", "Let pets roam to save time"]'::jsonb,1,'Laws about licensing and rabies protect both animals and people in the community.','original'),
('127.51.d.2.A',3,'A vet science student plans a project of caring for a flock of chickens and tracking their health for a semester. This is best called a:','["Scholarship exam", "Field trip report", "Supervised agricultural experience", "Banquet program"]'::jsonb,2,'An SAE is hands-on work with a plan, goals and an adult supervisor outside regular class time.','original'),
('127.51.d.2.A',2,'Who helps a student set up and review a veterinary science supervised experience?','["A stranger online", "Only the student''s classmates", "Nobody; it needs no oversight", "A teacher or other adult supervisor"]'::jsonb,3,'Supervision means an adult guides and checks the plan and the work.','original'),
('127.51.d.2.B',2,'Why should a student record dates, hours, and costs of an animal care project?','["To measure progress and show what was learned", "Because animals read them", "To make the project look bigger", "So records can be thrown away"]'::jsonb,0,'Good records show growth, costs and skills, and support awards and applications.','original'),
('127.51.d.2.B',3,'Which entry belongs in a vet-science project record book?','["A joke list", "A log of vaccines given to a pet, with dates", "A map of a mall", "A favorite recipe"]'::jsonb,1,'Accurate, dated animal care entries make records useful for evaluation.','original'),
('127.51.d.3.A',2,'Which activity builds leadership in a veterinary science class?','["Sitting out all club events", "Skipping meetings", "Leading a service project at an animal shelter", "Letting others do all the work"]'::jsonb,2,'Taking responsibility for a group service project builds leadership skills.','original'),
('127.51.d.3.B',2,'A chapter''s local program of activities for a vet science club could include:','["Keeping plans secret", "Cancelling all events", "Only voting without meeting", "Planning a pet-care awareness night"]'::jsonb,3,'A local program of activities lists the events, service and goals members plan for the year.','original'),
('127.51.d.3.B',3,'Members who help carry out the club''s yearly plan are:','["Taking part in a local program of activities", "Breaking chapter rules", "Skipping club business", "Doing unpaid tutoring only"]'::jsonb,0,'Reviewing and joining the planned events is how members support the program.','original'),
('127.51.d.3.C',2,'A resume for a vet-science student could list:','["Nothing, since experience does not count", "Volunteer hours at a shelter and chapter service", "Test scores from other subjects only", "Only favorite foods"]'::jsonb,1,'Documenting work, volunteering and service shows relevant experience.','original'),
('127.51.d.3.C',3,'Why update a record of animal-related experience each year?','["To make it longer than needed", "To avoid learning new skills", "To keep an accurate, current history for jobs and applications", "Because old items vanish on their own"]'::jsonb,2,'Current documentation supports resumes, scholarships and degree programs.','original'),
('127.51.d.4.A',2,'Why do vet workers learn proper animal restraint?','["To avoid wearing gloves", "To speed up payment", "To make animals fear the clinic", "To protect both the animal and the handler during care"]'::jsonb,3,'Safe restraint lowers the risk of bites, scratches and injuries.','original'),
('127.51.d.4.A',3,'Which is a safe way to lift a large dog?','["Bend the knees and get help to lift it", "Hold only by the front legs", "Lift fast with a bent back", "Lift while the dog is struggling, alone"]'::jsonb,0,'Using the legs and getting help protects the worker''s back and the dog''s joints.','original'),
('127.51.d.4.B',2,'A disease that can spread from animals to humans is called:','["Genetic", "Zoonotic", "Mechanical", "Nutritional"]'::jsonb,1,'Zoonotic diseases such as rabies move between animals and people.','original'),
('127.51.d.4.B',3,'Which step helps prevent spreading a zoonotic disease at work?','["Sharing food with patients", "Touching your face during procedures", "Washing hands after every animal contact", "Eating lunch in the exam room"]'::jsonb,2,'Hand washing and clean habits stop pathogens from moving between animals and people.','original'),
('127.51.d.4.C',2,'Which of these is a sanitation method for exam tables?','["Wiping once at the end of the week", "Spraying only air freshener", "Covering with a towel and leaving it", "Disinfecting the surface between patients"]'::jsonb,3,'Cleaning and disinfecting after each patient prevents the spread of germs.','original'),
('127.51.d.4.C',3,'Why are kennels cleaned and disinfected on a schedule?','["To reduce pathogens and keep animals healthy", "To save on supplies", "To keep animals awake", "To make the room smell stronger"]'::jsonb,0,'Regular sanitation controls disease in places where many animals live.','original'),
('127.51.d.4.D',2,'What does an SDS tell a clinic worker?','["What the animal weighs", "How to safely handle and store a chemical", "Who the pet owner is", "How much a chemical costs"]'::jsonb,1,'A safety data sheet lists hazards, first aid and handling for a chemical product.','original'),
('127.51.d.4.D',3,'A worker spills a cleaning chemical. Where should they check for the correct clean-up steps?','["The patient chart", "The price list", "The safety data sheet for the product", "A magazine"]'::jsonb,2,'The SDS gives spill response, protective gear and first aid information.','original'),
('127.51.d.4.E',2,'Before using clinical equipment such as clippers, a worker should:','["Use it only on people", "Borrow it without asking", "Try it without instruction", "Learn the correct and safe way to operate it"]'::jsonb,3,'Training prevents injuries to the animal and the user.','original'),
('127.51.d.4.E',3,'Which choice shows safe equipment use?','["Unplugging clippers before cleaning the blades", "Passing a running tool to a coworker", "Leaving blades running unattended", "Cleaning blades while plugged in"]'::jsonb,0,'Power should be off before cleaning to prevent cuts or shocks.','original'),
('127.51.d.4.F',2,'Where should used needles be placed?','["In the regular trash", "In a labeled sharps container", "In a coat pocket", "On the counter"]'::jsonb,1,'A puncture-proof sharps container prevents needle sticks.','original'),
('127.51.d.4.F',3,'Which waste belongs in a biohazard container?','["Empty food cans", "Unused office paper", "Items soiled with blood or body fluids", "Clean paper towels"]'::jsonb,2,'Contaminated materials must be separated to prevent disease spread.','original'),
('127.51.d.5.A',3,'Why do vet students study the history of animal medicine?','["To memorize only dates", "To skip current laws", "To avoid learning anatomy", "To see how past events and trends shaped current practice"]'::jsonb,3,'Understanding history helps explain why today''s methods and rules exist.','original'),
('127.51.d.5.A',4,'Which topic is a current issue studied in veterinary medicine?','["Antibiotic resistance in animal treatment", "Pricing of school lunches", "Rules for car racing", "Fashion trends"]'::jsonb,0,'Antibiotic resistance affects both animal and human health and shapes practice.','original'),
('127.51.d.5.B',3,'Veterinary medical ethics includes:','["Keeping fees secret from owners", "Making decisions about animal welfare and euthanasia with care", "Ignoring animal pain", "Sharing a client''s records for fun"]'::jsonb,1,'Ethics guides how vets weigh animal welfare, owner wishes and professional duty.','original'),
('127.51.d.5.B',4,'A vet is asked to perform a procedure that would harm the animal with no medical reason. The ethical response is to:','["Do it for extra pay", "Let an assistant do it instead", "Decline and explain the animal''s welfare concerns", "Do it quickly and say nothing"]'::jsonb,2,'Professional ethics put animal welfare and medical need before convenience.','original'),
('127.51.d.5.C',3,'A clinic''s written policies on records and drug storage reflect:','["Random preferences", "Rules from other industries", "Only the owner''s mood", "Local, state, and federal rules for veterinary medicine"]'::jsonb,3,'Clinic policies follow laws and regulations for safe, legal practice.','original'),
('127.51.d.5.C',4,'Why do clinics have written protocols for common procedures?','["To keep care consistent, safe, and legal", "To hide mistakes", "To slow down staff", "To avoid training"]'::jsonb,0,'Standard procedures reduce errors and meet legal requirements.','original'),
('127.51.d.6.A',2,'The human-animal bond affects veterinary care because owners:','["Never care about their pets", "Often make care decisions based on how close they are to the pet", "Follow only the cheapest advice", "Never visit a clinic"]'::jsonb,1,'The bond influences how clients view treatment, cost and comfort.','original'),
('127.51.d.6.A',3,'A client is grieving a pet''s death. Which response shows understanding of the bond?','["Rushing them out the door", "Joking about the loss", "Speaking with kindness and giving them time", "Talking only about the bill"]'::jsonb,2,'Compassion supports the client and builds trust.','original'),
('127.51.d.6.B',2,'Which is good client communication?','["Using only medical jargon", "Avoiding eye contact", "Interrupting the owner", "Explaining a treatment plan in clear, simple words"]'::jsonb,3,'Clear language helps owners understand and follow care instructions.','original'),
('127.51.d.6.B',3,'An owner seems confused about a medicine schedule. What should the assistant do?','["Repeat it in plain language and provide it in writing", "Say it faster", "Assume they understood", "Tell them to ask the internet"]'::jsonb,0,'Checking understanding and giving written steps improves compliance.','original'),
('127.51.d.6.C',2,'Which is a way a clinic markets its services?','["Avoiding all communication", "Sharing pet health tips and reminders with clients", "Hiding its location", "Closing during business hours"]'::jsonb,1,'Marketing helps clients learn about services and stay engaged.','original'),
('127.51.d.6.C',3,'How does good marketing help a veterinary practice?','["It replaces medical care", "It stops disease directly", "It brings in clients and supports the practice''s success", "It removes the need for staff"]'::jsonb,2,'Marketing attracts and keeps clients, which supports the business and animal care.','original'),
('127.51.d.6.D',2,'Which technology helps a clinic manage appointments?','["A chalkboard in the parking lot", "A single sticky note", "Paper notes thrown away daily", "Computer scheduling software"]'::jsonb,3,'Software handles scheduling, records and reminders efficiently.','original'),
('127.51.d.6.D',3,'Electronic medical records help a clinic by:','["Storing patient histories so they are quick to find", "Removing the need for accuracy", "Preventing owners from calling", "Making notes unreadable"]'::jsonb,0,'Electronic records are organized, searchable and easily shared with permission.','original'),
('127.51.d.7.A',3,'The prefix ''hyper-'' in veterinary terms means:','["Around", "Above or excessive", "Without", "Below or lacking"]'::jsonb,1,'Hyper- means excessive, as in hyperthermia, a high body temperature.','original'),
('127.51.d.7.A',4,'In ''gastritis'', the suffix ''-itis'' means:','["Removal", "Study of", "Inflammation", "Cutting"]'::jsonb,2,'-itis means inflammation, so gastritis is inflammation of the stomach.','original'),
('127.51.d.7.B',2,'Why is correct spelling of veterinary terms important in medical records?','["It makes the chart longer", "It only matters for owners", "It does not matter", "Errors can cause confusion or mistakes in treatment"]'::jsonb,3,'Precise terms prevent misreads of diagnoses and medications.','original'),
('127.51.d.7.B',3,'Which is the correct spelling of the animal term for a female dog giving birth?','["Whelping", "Wheeling", "Welping", "Whelpping"]'::jsonb,0,'Whelping is the term for a dog giving birth.','original'),
('127.51.d.7.C',2,'The term ''dorsal'' refers to the:','["Belly side", "Back or top side", "Front end", "Tail only"]'::jsonb,1,'Dorsal means toward the back (spine side).','original'),
('127.51.d.7.C',3,'Which direction term means toward the head?','["Caudal", "Ventral", "Cranial", "Medial"]'::jsonb,2,'Cranial means toward the head; caudal means toward the tail.','original'),
('127.51.d.8.A',2,'Animal breeds are identified by:','["Owner''s address", "Name tags only", "Time of day", "Physical traits such as size, coat, and ear shape"]'::jsonb,3,'Breed characteristics are visible features inherited within a group.','original'),
('127.51.d.8.A',3,'A Holstein is a breed of:','["Dairy cattle", "Sheep", "Horse", "Swine"]'::jsonb,0,'Holsteins are known for high milk production.','original'),
('127.51.d.8.B',3,'Which is an example of abnormal behavior in a normally social dog?','["Wagging its tail", "Sudden hiding and refusing food", "Playing with toys", "Sleeping after a walk"]'::jsonb,1,'A sudden change in behavior can signal pain or illness.','original'),
('127.51.d.8.B',4,'Why compare behavior among species?','["Behavior has no medical value", "Only dogs have behaviors", "Normal behavior differs for dogs, cats, horses, and livestock", "All species behave the same"]'::jsonb,2,'Knowing species norms helps spot signs of stress or illness.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_8_v1'
from (values
('127.51.d.8.C',2,'Why do handlers approach horses from the side where the horse can see them?','["Because horses cannot hear", "To scare it", "To speed up the exam", "To avoid startling the animal"]'::jsonb,3,'Calm, visible approaches reduce the chance of kicks and injuries.','original'),
('127.51.d.8.C',3,'Which is a basic restraint tool for a cat?','["A towel wrap", "A rope tied to a fence", "A spiked collar", "A heavy chain"]'::jsonb,0,'A towel wrap safely limits movement and calms many cats.','original'),
('127.51.d.9.A',2,'Which body system includes bones that support the animal?','["Respiratory", "Skeletal", "Urinary", "Digestive"]'::jsonb,1,'The skeletal system supports the body and protects organs.','original'),
('127.51.d.9.A',3,'The main job of the respiratory system is to:','["Filter blood only", "Produce hormones only", "Move oxygen in and carbon dioxide out", "Digest food"]'::jsonb,2,'Lungs exchange gases to supply oxygen to the body.','original'),
('127.51.d.9.B',3,'Which statement shows body systems work together?','["The nervous system stops all others", "The digestive system never needs blood", "Each system works alone", "The circulatory system carries oxygen taken in by the respiratory system"]'::jsonb,3,'Systems are interdependent; blood moves oxygen from the lungs to tissues.','original'),
('127.51.d.9.B',4,'If the kidneys fail to remove wastes, what other system is affected?','["Circulatory, because wastes build up in the blood", "None", "Only the skeletal system", "Only the hair coat"]'::jsonb,0,'Kidney failure allows toxins to accumulate in the blood and affect many organs.','original'),
('127.51.d.10.A',2,'Which feed is a common source of protein for dogs?','["Plain water", "Meat-based dog food", "Salt only", "Sand"]'::jsonb,1,'Meat and legumes supply protein, an essential nutrient.','original'),
('127.51.d.10.A',3,'Hay and pasture are classes of feed called:','["Supplements only", "Concentrates", "Roughages", "Minerals only"]'::jsonb,2,'Roughages are high-fiber feeds for livestock like horses and cattle.','original'),
('127.51.d.10.B',3,'A feed additive such as a vitamin supplement is used to:','["Replace all feed", "Reduce water needs", "Make food less safe", "Fill nutrient gaps in the diet"]'::jsonb,3,'Additives provide nutrients or other benefits the basic ration lacks.','original'),
('127.51.d.10.B',4,'Why must feed additives be used carefully?','["Too much or the wrong type can harm the animal", "They are always required by law", "They only change color", "They never matter"]'::jsonb,0,'Dosage and species suitability matter for safety.','original'),
('127.51.d.10.C',3,'A senior dog with kidney trouble often needs:','["The same food as a puppy", "A diet formulated for its condition", "No food at all", "Only table scraps"]'::jsonb,1,'Life stage and health conditions change dietary needs.','original'),
('127.51.d.10.C',4,'Moldy feed is a feed-quality issue because it can:','["Add extra vitamins", "Increase water content safely", "Produce toxins that make animals sick", "Improve digestion"]'::jsonb,2,'Mold can release mycotoxins that harm health.','original'),
('127.51.d.10.D',3,'A prescription diet differs from a regular diet in that it:','["Is only for humans", "Has no nutrients", "Costs less always", "Is formulated to treat a specific medical condition"]'::jsonb,3,'Therapeutic diets are used to help manage disease under veterinary direction.','original'),
('127.51.d.10.D',4,'To compare two foods, a vet reads the:','["Guaranteed analysis and ingredient list", "Bag color", "Brand logo", "Barcode only"]'::jsonb,0,'Labels show nutrient percentages and ingredients for comparison.','original'),
('127.51.d.11.A',2,'A healthy dog usually has:','["Refusal to drink", "Bright eyes, a clean coat, and a good appetite", "Dull eyes and a matted coat", "Constant coughing"]'::jsonb,1,'Alert, bright animals with normal eating habits are generally healthy.','original'),
('127.51.d.11.A',3,'Which sign suggests an animal may be unhealthy?','["Playful energy", "Clear eyes", "Lethargy with a loss of appetite", "Normal stools"]'::jsonb,2,'Lethargy and appetite change are common signs of illness.','original'),
('127.51.d.11.B',3,'Vital signs commonly checked in an exam include:','["Hair length", "Collar size", "Eye color", "Temperature, pulse, and respiration"]'::jsonb,3,'TPR are core vital signs for assessing health.','original'),
('127.51.d.11.B',4,'Normal vital sign ranges differ because:','["Each species and size has its own healthy range", "Only age matters, never species", "All animals share one range", "They are random"]'::jsonb,0,'Heart rate and temperature vary by species and size.','original'),
('127.51.d.11.C',3,'To take a dog''s pulse, a technician commonly:','["Presses the nose", "Feels the femoral artery in the inner thigh", "Holds the tail", "Checks the ear tip"]'::jsonb,1,'The femoral pulse is easily felt in dogs and cats.','original'),
('127.51.d.11.C',4,'A rectal temperature is taken using:','["A dry glass rod forced in", "A tape measure", "A lubricated thermometer", "A stethoscope only"]'::jsonb,2,'Lubrication and gentle technique make the measurement safe.','original'),
('127.51.d.11.D',3,'Which factor can raise an animal''s heart rate temporarily?','["A calm voice", "Quiet rest", "A cool room", "Stress or fear"]'::jsonb,3,'Fear and excitement increase heart and respiration rates.','original'),
('127.51.d.11.D',4,'Why consider age when interpreting vital signs?','["Young animals have higher heart rates than adults", "Age does not affect physiology", "They never change", "Older animals always have the highest"]'::jsonb,0,'Normal values shift across life stages.','original'),
('127.51.d.11.E',2,'A physical exam usually begins with:','["Removing hair", "Observing the animal''s general appearance", "Surgery", "Giving injections"]'::jsonb,1,'Observation reveals posture, behavior and body condition before hands-on steps.','original'),
('127.51.d.11.E',3,'During a physical exam, the vet listens to the heart using a:','["Microscope", "Syringe", "Stethoscope", "Scalpel"]'::jsonb,2,'Auscultation uses a stethoscope to hear heart and lung sounds.','original'),
('127.51.d.11.F',3,'The regional approach to assessing health means examining:','["The animal''s paperwork only", "Only the paws", "Only the eyes", "Each area of the body in an organized order"]'::jsonb,3,'Systematically checking head, neck, trunk and limbs ensures nothing is missed.','original'),
('127.51.d.11.F',4,'A benefit of an anatomical regional exam is that it:','["Reduces the chance of overlooking an abnormality", "Replaces lab tests", "Needs no training", "Makes the exam shorter every time"]'::jsonb,0,'A consistent order helps find problems.','original'),
('127.51.d.11.G',3,'A cat weighs 8 pounds today and weighed 10 pounds last month. How much did it lose?','["3 pounds", "2 pounds", "1 pound", "18 pounds"]'::jsonb,1,'10 minus 8 equals 2 pounds, a 20 percent loss, which is significant.','original'),
('127.51.d.11.G',4,'A dog weighs 44 pounds. About how many kilograms is that (1 kg = 2.2 lb)?','["10 kg", "44 kg", "20 kg", "97 kg"]'::jsonb,2,'44 divided by 2.2 equals 20 kilograms.','original'),
('127.51.d.11.H',3,'A growth chart shows a puppy''s weight rising steadily over weeks. This pattern suggests:','["No change", "Illness always", "Weight loss", "Normal growth"]'::jsonb,3,'A steady upward line matches healthy growth.','original'),
('127.51.d.11.H',4,'On a weight graph, a sudden drop in an adult dog''s line may signal:','["A health problem that needs attention", "Perfect health", "Better nutrition always", "A broken chart"]'::jsonb,0,'Rapid unexplained weight loss warrants investigation.','original'),
('127.51.d.12.A',3,'Vaccines help an animal by:','["Changing the animal''s DNA", "Training the immune system to recognize a pathogen", "Killing all bacteria in the body", "Replacing food"]'::jsonb,1,'Vaccines prime immunity without causing the full disease.','original'),
('127.51.d.12.A',4,'A disease spread by direct contact between animals is:','["Always airborne only", "Never contagious", "Transmitted by touching or close contact", "Spread only by plants"]'::jsonb,2,'Direct transmission occurs through contact, bites or fluids.','original'),
('127.51.d.12.B',3,'A virus differs from a bacterium because a virus:','["Is visible without tools", "Makes its own food", "Is a large animal", "Needs a host cell to reproduce"]'::jsonb,3,'Viruses replicate only inside host cells.','original'),
('127.51.d.12.B',4,'Canine parvo, which attacks the gut of puppies, is caused by which kind of pathogen?','["A viral agent", "A bacterium", "A fungus", "A tapeworm"]'::jsonb,0,'Canine parvo is a viral disease that attacks the gut.','original'),
('127.51.d.12.C',3,'A respiratory infection can show up as:','["Gaining weight", "Coughing and nasal discharge", "Limping only", "Hair color change"]'::jsonb,1,'Respiratory disease affects the airways and lungs.','original'),
('127.51.d.12.C',4,'Diarrhea and vomiting point most directly to disease in the:','["Skeletal system", "Reproductive system", "Digestive system", "Integumentary system"]'::jsonb,2,'These signs indicate GI tract disturbance.','original'),
('127.51.d.12.D',3,'Fleas and ticks are examples of:','["Viruses", "Internal parasites", "Bacteria", "External parasites"]'::jsonb,3,'They live on the outside of the host.','original'),
('127.51.d.12.D',4,'Roundworms and hookworms are classified as:','["Internal parasites", "External parasites", "Protozoa only", "Fungi"]'::jsonb,0,'They live inside the host''s intestines.','original'),
('127.51.d.12.E',3,'A parasite life cycle describes:','["The drug used", "The stages a parasite goes through from egg to adult", "Only the adult stage", "The host''s diet"]'::jsonb,1,'Knowing the cycle shows where it can be stopped.','original'),
('127.51.d.12.E',4,'Why do vets learn life cycles of parasites?','["To pick leash types", "To decide on grooming", "To time treatment and prevention at the right stage", "To order food"]'::jsonb,2,'Breaking the cycle controls infestations.','original'),
('127.51.d.12.F',3,'Tapeworms in dogs can be transmitted when a dog:','["Takes a bath", "Eats dry kibble from a sealed bag", "Plays fetch", "Swallows an infected flea"]'::jsonb,3,'Dogs get certain tapeworms by eating fleas carrying larvae.','original'),
('127.51.d.12.F',4,'Heartworm is spread by:','["Mosquitoes", "Dry air", "Contaminated water bowls only", "Direct touching of paws"]'::jsonb,0,'Mosquitoes carry larvae from animal to animal.','original'),
('127.51.d.12.G',3,'A fecal flotation test is used to find:','["Bone fractures", "Parasite eggs in stool", "Blood sugar", "Vitamin levels"]'::jsonb,1,'The test floats eggs so they can be seen under a microscope.','original'),
('127.51.d.12.G',4,'Which test can detect heartworm?','["An X-ray of the paw", "A fecal float", "A blood test for antigens", "A skin scraping for lice"]'::jsonb,2,'Heartworm antigen tests are done on blood.','original'),
('127.51.d.12.H',3,'A common treatment for intestinal worms is:','["A vitamin", "A haircut", "A bath only", "A deworming medication"]'::jsonb,3,'Dewormers are given according to the parasite found.','original'),
('127.51.d.12.H',4,'Prevention products given monthly protect pets from:','["Heartworm and some other parasites", "Nail growth", "Dental decay", "Hunger"]'::jsonb,0,'Monthly preventives interrupt parasite life cycles.','original'),
('127.51.d.13.A',3,'A fecal sample should be:','["Old and unlabeled", "Fresh and labeled with the patient''s information", "Mixed with others", "Frozen for a year"]'::jsonb,1,'Proper handling preserves the sample and prevents mix-ups.','original'),
('127.51.d.13.A',4,'Why wear gloves when collecting a urine sample?','["To make the sample bigger", "Because the dog requires it", "To avoid exposure to pathogens", "To keep hands warm"]'::jsonb,2,'Body fluids can carry disease.','original'),
('127.51.d.13.B',3,'A urinalysis can help detect:','["Broken bones", "Dental tartar", "Poor eyesight", "Kidney problems and infection"]'::jsonb,3,'Urine tests show how kidneys and the urinary tract are working.','original'),
('127.51.d.13.B',4,'Blood tests are commonly run to check:','["Organ function and infection", "Only nail length", "Collar fit", "Hair color"]'::jsonb,0,'A CBC and chemistry panel give information on organs and cells.','original'),
('127.51.d.13.C',3,'A high white blood cell count often suggests:','["Perfect health", "Infection or inflammation", "Poor hair coat", "Dehydration only"]'::jsonb,1,'White cells increase to fight infection.','original'),
('127.51.d.13.C',4,'When comparing results to normal ranges, a value far outside the range should be:','["Ignored", "Rounded to match", "Reported to the veterinarian", "Erased"]'::jsonb,2,'Abnormal results need professional interpretation.','original'),
('127.51.d.14.A',3,'After use, surgical instruments should be:','["Stored wet", "Shared without cleaning", "Left dirty overnight", "Cleaned and sterilized before storing"]'::jsonb,3,'Cleaning and sterilizing prevents infection.','original'),
('127.51.d.14.A',4,'Equipment maintenance logs are kept to:','["Track cleaning, calibration, and repairs", "Hide problems", "Replace training", "Reduce records"]'::jsonb,0,'Maintenance logs show devices are safe and working.','original'),
('127.51.d.14.B',3,'A veterinary medical record must be:','["Short and vague", "Accurate, complete, and kept confidential", "Left out in the lobby", "Shared on social media"]'::jsonb,1,'Records document care and protect client privacy.','original')
