('127.51.d.17.B',3,'Controlled drugs in a clinic must be:','["Left on the counter", "Locked, logged, and accounted for", "Unrecorded", "Shared freely"]'::jsonb,1,'Law requires secure storage and records.','original'),
('127.51.d.17.B',4,'Expired medications should be:','["Sold at a discount", "Given to patients", "Removed and disposed of properly", "Kept mixed with fresh stock"]'::jsonb,2,'Expired drugs may be ineffective or unsafe.','original'),
